function canMeasure(a: number, b: number, target: number): boolean {
  if (target > a + b) return false;
  const seen = new Set<number>();
  const key = (x: number, y: number) => x * (b + 1) + y;
  const queue: number[][] = [[0, 0]];
  seen.add(0);
  for (let i = 0; i < queue.length; i++) {
    const [x, y] = queue[i];
    if (x + y === target) return true;
    const pourAB = Math.min(x, b - y), pourBA = Math.min(y, a - x);
    const next = [[a, y], [x, b], [0, y], [x, 0], [x - pourAB, y + pourAB], [x + pourBA, y - pourBA]];
    for (const [nx, ny] of next) {
      const k = key(nx, ny);
      if (!seen.has(k)) { seen.add(k); queue.push([nx, ny]); }
    }
  }
  return false;
}

