        if target > a + b:
            return False
        seen = {(0, 0)}
        q = deque([(0, 0)])
        while q:
            x, y = q.popleft()
            if x + y == target:
                return True
            ab, ba = min(x, b - y), min(y, a - x)
            for s in ((a, y), (x, b), (0, y), (x, 0), (x - ab, y + ab), (x + ba, y - ba)):
                if s not in seen:
                    seen.add(s)
                    q.append(s)
        return False

